  (20539, 20515, 1, 'hujungkan, letak di hujung', 'to put at the end, tip'),
  (20540, 20516, 1, 'orang; penjodoh bilangan untuk manusia (kata pinjaman daripada Bahasa Melayu terkini; lazim digunakan untuk bilangan empat ke atas seperti ''pitu'''' urang dendo'', menggantikan atau melengkapkan sistem bilangan asli ''-angan'')', 'person; numeral classifier for human beings (modern loanword from Malay; commonly used for numbers four and above, e.g. ''pitu'''' urang dendo'', supplementing or replacing the native ''-angan'' counting system)'),
  (20541, 20516, 2, 'orang, manusia (kata pinjaman daripada Bahasa Melayu; padanan asli dalam Bahasa Bajau Sama ialah ''jomo'')', 'person, human being (Malay loanword; indigenous West Coast Bajau equivalent is ''jomo'')'),
  (20542, 20517, 1, 'orang; varian sebutan atau ejaan bagi ''urang'' (kata pinjaman daripada Bahasa Melayu untuk penjodoh bilangan manusia atau kata nama orang)', 'person; variant form of ''urang'' (Malay loanword used as human classifier or noun)'),
  (20543, 20518, 1, 'sebuah, sebiji; satu unit bagi buah, benda berbentuk bulat, atau struktur besar seperti rumah dan sungai (terbitan ''de-'' + ''eN-'' + ''bua'''')', 'one, a, an; a single unit of fruit, round object, or large structure/feature like house or river (derived from ''de-'' + ''eN-'' + ''bua'''')'),
  (20544, 20519, 1, 'ungut, seungut; sukatan isipadu tradisional bersamaan separuh bahagian bawah tempurung kelapa (lazimnya digunakan untuk menyukat beras atau cecair)', 'ungut; traditional dry volume measure equal to the bottom half of a coconut shell (traditionally used for measuring rice or liquids)'),
  (20545, 20520, 1, 'cubit, secubit; sukatan sedikit yang diambil menggunakan hujung jari (seperti garam, gula, serbuk kunyit)', 'pinch; small measure taken between the fingertips (such as salt, sugar, turmeric)'),
  (20546, 20521, 1, 'cupak; sukatan tradisional bijirin atau beras (dalam tradisi Bajau Sama, 12 supak bersamaan 1 gantang; berbeza dengan sukatan Melayu piawai 4 cupak = 1 gantang)', 'supak / traditional dry volume measure for rice (in West Coast Bajau tradition, 12 supak equal 1 gantang, unlike standard Malay where 4 cupak = 1 gantang)'),
  (20547, 20522, 1, 'gantang; sukatan tradisional isipadu bijirin dan beras (1 gantang = 12 supak Bajau Sama; 10 gantang = 1 bandu)', 'gantang; traditional measure of volume for paddy or milled rice (1 gantang = 12 Bajau Sama supak; 10 gantang = 1 bandu)'),
  (20548, 20523, 1, 'bandu; unit sukatan tradisional Bajau Sama bersamaan 10 gantang beras (sering dijadikan ukuran asas bagi zakat padi atau ''zakat paray'', di mana setiap bandu kesepuluh disedekahkan kepada yang berhak)', 'bandu; traditional Bajau Sama volume measure equal to 10 gantang of rice (traditionally used as baseline for rice tithes/zakat paray, where every tenth bandu is given to charity)');
INSERT OR REPLACE INTO `senses` (`id`, `entry_id`, `order_index`, `definition_ms`, `definition_en`) VALUES
  (20549, 20524, 1, 'guni, karung; sukatan muatan beras atau padi (1 karung bersamaan 3 bandu atau 30 gantang padi)', 'sack; measure of rice/paddy volume (1 karung equals 3 bandu or 30 gantang of paddy)'),
  (20550, 20524, 2, 'guni, karung (beg besar daripada anyaman atau kain tebal untuk mengisi bijirin atau barangan)', 'sack, bag (large bag made of burlap or thick plastic for holding grains or goods)'),
  (20551, 20525, 1, 'sibur, petak; sukatan keluasan tanah bagi satu bahagian atau petak sawah padi', 'sibur; measure of land area representing a division or plot of a wet rice paddy field'),
  (20552, 20526, 1, 'jengkal; sukatan jarak antara hujung ibu jari dengan hujung jari tangan (lazimnya ''de-koo tarik'' merujuk jarak ibu jari ke jari tengah/hantu, dan ''de-koo tunduk'' merujuk ibu jari ke jari telunjuk)', 'finger-span; traditional distance measure between the tip of the thumb and a fingertip (de-koo tarik: thumb to middle finger; de-koo tunduk: thumb to index finger)'),
  (20553, 20527, 1, 'sejengkal; sukatan ukuran jarak sejengkal tangan (dari ibu jari ke jari kelengkeng atau jari tengah)', 'one finger-span; span of an outstretched hand'),
  (20554, 20528, 1, 'jengkal; jarak rentangan tapak tangan', 'span, finger-span; span of the outstretched hand'),
  (20555, 20529, 1, 'sehasta; sukatan jarak dari siku hingga ke hujung jari tengah tangan', 'cubit, one cubit; traditional measurement of distance from the elbow to the tip of the middle finger'),
  (20556, 20530, 1, 'depa, sedepa; ukuran jarak dari hujung jari tangan kiri ke hujung jari tangan kanan apabila kedua-dua belah tangan didepangkan', 'fathom, span of outstretched arms; measure of distance from fingertip to fingertip of two outstretched arms'),
  (20557, 20531, 1, 'ruas; sukatan jarak antara dua ruas atau sendi (seperti ruas buluh, tebu, jarak dari pergelangan tangan ke siku, atau siku ke bahu)', 'internode, segment; measure of distance between two nodes or segments (of bamboo, sugarcane, or anatomical segments from wrist to elbow, elbow to shoulder)'),
  (20558, 20532, 1, 'jenis, macam; penjodoh bilangan untuk menyatakan jenis, kategori, atau ragam benda', 'kind, sort, type, category; classifier/quantifier denoting kinds or types of things'),
  (20559, 20532, 2, 'bangsa, suku kaum, etnik', 'nation, race, ethnic group'),
  (20560, 20533, 1, 'tompok, longgok, timbunan; penjodoh bilangan untuk benda yang bertimbun atau berlonggok (seperti tanah, pasir, batu)', 'pile, stack, mound, heap; classifier/measure noun for heaps or mounds of items (such as earth, sand, stones)'),
  (20561, 20534, 1, 'kerat, keping, ketul, potongan; penjodoh bilangan untuk bahagian benda yang telah dipotong atau dikerat (seperti kayu api, daging, kain, kuih)', 'piece, slice, cut segment; classifier/measure noun for sliced or cut pieces of objects (such as firewood, meat, cloth, cake)'),
  (20562, 20535, 1, 'titis, titik; penjodoh bilangan untuk cecair yang menitis (seperti air, darah, peluh, ubat)', 'drop; classifier/measure noun for drops of liquid (such as water, blood, sweat, medicine)'),
  (20563, 20536, 1, 'lempeng, berkas; penjodoh bilangan untuk daun tembakau kering (sigup) yang dilempengkan atau diikat rapi mengikut kaedah tradisional', 'bundle, pressed slab; classifier/measure noun for pressed slabs or wrapped bundles of dried cured tobacco (sigup)'),
  (20564, 20537, 1, 'sikat; penjodoh bilangan untuk sesikat pisang (saging)', 'hand, comb; classifier for a hand/comb of bananas (saging)'),
  (20565, 20538, 1, 'tandan; penjodoh bilangan untuk buah yang bergugus besar pada tangkainya (seperti pisang, kelapa, kelapa sawit)', 'bunch, stalk, cluster; classifier for large bunches/stalks of fruit (such as bananas, coconuts, palm fruit)'),
  (20566, 20539, 1, 'ikat; penjodoh bilangan untuk benda-benda yang diikat bersama (seperti kayu api, sayur-sayuran, ikan)', 'tied bundle, bunch; classifier for items bundled or tied together (such as firewood, vegetables, fish)'),
  (20567, 20540, 1, 'kawan, kawanan, kelompok; penjodoh bilangan untuk sekumpulan haiwan atau ternakan (seperti lembu, kambing, kerbau)', 'herd, flock, troop; classifier/measure noun for a group or herd of livestock animals (such as cattle, goats, water buffaloes)'),
  (20568, 20541, 1, 'mangkuk (bekas makanan berlekuk untuk mengisi lauk berkuah atau cecair)', 'bowl (container for holding food or soup)'),
  (20569, 20541, 2, 'semangkuk; sukatan isipadu muatan satu mangkuk makanan atau cecair', 'bowlful; measure of volume contained in a bowl'),
  (20570, 19040, 2, 'buah, biji, batang; penjodoh bilangan untuk buah-buahan, benda bulat, atau objek dan ciri geografi yang besar (seperti rumah, sungai, telur, tembikai)', 'classifier for fruits, round objects, or very large structures and geographical features (such as houses, rivers, eggs, watermelons)'),
  (20571, 19533, 2, 'ulas, pangsa; penjodoh bilangan untuk bahagian atau ulas isi buah (seperti durian, cempedak, limau)', 'section, carpel, segment; classifier for sections/carpels of segmented fruits (such as durian, cempedak, citrus)'),
  (20572, 19578, 2, 'sudu, sesudu; sukatan sebanyak muatan satu sudu (cth. de-n-sudu'' sira'')', 'spoonful; measure of volume contained in a spoon (e.g. de-n-sudu'' sira'')'),
  (20573, 20542, 1, 'oleh; penanda pelaku dalam binaan ayat pasif (kata kerja berimbuhan awalan te- atau sisipan -in-)', 'by; marker of the oblique actor/agent in passive constructions (with te- or -in- passives)'),
  (20574, 20542, 2, 'kerana, oleh sebab, disebabkan; memperkenalkan frasa sendi keadaan atau sebab bagi kata kerja tak transitif', 'on account of, because of; introduces a circumstantial prepositional phrase expressing cause or condition'),
  (20575, 20542, 3, 'cara, bagaimana; digunakan bersama klausa pelengkap bagi menyatakan cara sesuatu perbuatan dilakukan (lazim didahului kata tanya ''pian'')', 'manner, way; used with complement clauses expressing the manner in which an action is performed (often preceded by ''pian'')'),
  (20576, 20543, 1, 'dengan, dan, bersama; bentuk ringkas bagi kata sendi dan kata hubung ''engko''''', 'with, and; shortened colloquial form of the preposition and coordinating conjunction ''engko'''''),
  (20577, 20544, 1, 'sampai, hingga, sehingga; kata sendi nama takat yang menandakan batas masa atau tempat', 'until, up to; extent preposition marking a limit of time, distance, or boundary'),
  (20578, 20544, 2, 'sehingga, sampai; kata hubung pancangan yang memperkenalkan klausa takat atau akibat', 'until, so that; subordinator introducing extent or result clauses'),
  (20579, 19259, 2, 'oleh; kata sendi penanda pelaku dalam binaan pasif (cth. ''bineli ling iyaku'' = dibeli oleh saya; ''pina''an ling jomo'' = diberitahu oleh orang)', 'by; agentive preposition marking the actor in passive constructions (e.g. ''bineli ling iyaku'' = bought by me)'),
  (20580, 20545, 1, 'wahai, aduhai, amboi, wah; seruan yang menyatakan perasaan terkejut, kagum, atau terperanjat', 'expression of surprise, astonishment, or wonder (''wow!'', ''oh my!'')'),
  (20581, 20546, 1, 'masakan, adakah begitu!; seruan yang menyatakan rasa hairan, sangsi, atau terperanjat terhadap sesuatu khabar atau peristiwa', 'expression of surprise, disbelief, or astonishment (''really?!'', ''how can it be?!'')'),
  (20582, 20547, 1, 'hoi, eh, ooi; seruan jengkel, teguran, atau panggilan menarik perhatian', 'expression of annoyance, irritation, or attention-getting call (''hey!'', ''oi!'')'),
  (20583, 20548, 1, 'suh, hus; seruan atau bunyi yang dibuat khas untuk menghalau ayam', 'sound made to shoo away chickens (''shoo!'')'),
  (20584, 20549, 1, 'hus, chiss; seruan atau bunyi yang dibuat khas untuk menghalau anjing', 'sound made to shoo away dogs (''shoo!'', ''scram!'')'),
  (20585, 20550, 1, 'aduh, adoi; seruan untuk menyatakan rasa sakit fizikal, keluhan, atau rintihan', 'ouch, oh dear; exclamation expressing physical pain, distress, or groaning'),
  (20586, 20551, 1, 'adoi; varian sebutan bagi kata seru rasa sakit atau keluhan ''adui''', 'ouch, oh; phonetic variant of ''adui'' expressing pain or distress'),
  (20587, 20552, 1, 'ya, baiklah, jom, (Sabah) -bah; partikel atau seruan yang menyatakan persetujuan, permulaan tindakan, atau penegas ujaran yang sangat lazim dalam pertuturan di Sabah', 'all right, okay, let''s go; conversational particle/tag expressing agreement, initiation of action, or emphatic confirmation widely used in Sabah'),
  (20588, 19285, 2, 'dari, daripada; kata sendi nama yang menandakan punca atau pergerakan menjauhi sesuatu tempat atau objek (cth. ''pelaan man paray é'' = pergi/beredar dari padi itu)', 'from, away from; source preposition indicating departure or movement away from a place or object'),
  (20589, 20553, 1, 'saya, aku; kata ganti nama diri pertama tunggal (bebas / tidak terikat)', 'I, me (1st person singular independent pronoun)'),
  (20590, 20554, 1, 'kita; kata ganti nama diri pertama jamak inklusif (merangkumi penutur dan pendengar / orang yang diajak bercakap)', 'we, us (1st person plural inclusive independent pronoun, including the addressee)'),
  (20592, 20556, 1, 'kami; kata ganti nama diri pertama jamak eksklusif (merangkumi penutur dan kumpulannya, tetapi tidak termasuk pendengar). Dalam nahu Bajau Samah, ''kami'' juga berfungsi sebagai penanda pelaku Set I (tiada bentuk enklitik khusus)', 'we, us (1st person plural exclusive independent pronoun, excluding the addressee; also functions as Set I actor marker)'),
  (20593, 20557, 1, 'kau, kamu, awak; kata ganti nama diri kedua tunggal (bebas / tidak terikat)', 'you (2nd person singular independent pronoun)'),
  (20594, 20558, 1, 'kamu semua, kalian; kata ganti nama diri kedua jamak', 'you, you all (2nd person plural independent pronoun)'),
  (20595, 20559, 1, 'kalian, kamu semua; bentuk pendek atau varian percakapan bagi kaam (kata ganti nama diri kedua jamak). Lihat kaam.', 'you all; shortened conversational variant of kaam (2nd person plural pronoun). See kaam.'),
  (20596, 20560, 1, 'dia, ia; varian transkripsi linguistik bagi io (kata ganti nama diri ketiga tunggal). Bentuk baku rasmi ialah io. Lihat io.', 'he, she, it; linguistic transcription variant of standard io (3rd person singular pronoun). See io.'),
  (20597, 20561, 1, 'kita; kata ganti nama diri pertama jamak inklusif terikat (enklitik pemunya dan penanda pelaku bukan subjek, cth. ''kampung-ti'' = kampung kita, ''pemia-ti'' = kita cari)', 'our, by us (inclusive); 1st person plural inclusive enclitic pronoun (marks possessor on nouns and non-subject actor on verbs)'),
  (20598, 20562, 1, '-mu, kamu, awak; kata ganti nama diri kedua tunggal terikat (enklitik pemunya dan penanda pelaku bukan subjek, cth. ''dangan-nu'' = kawanmu, ''buan-nu'' = kamu berikan)', 'your, yours, by you; 2nd person singular enclitic pronoun (marks possessor on nouns and non-subject actor on transitive verbs)'),
  (20599, 20563, 1, 'kalian, kamu semua; kata ganti nama diri kedua jamak terikat (enklitik pemunya dan penanda pelaku, cth. ''buan-in bi'' = berikanlah oleh kalian, ''ruma''-bi'' = rumah kalian)', 'your, yours, by you all; 2nd person plural enclitic pronoun (marks possessor or actor among multiple addressees)');
INSERT OR REPLACE INTO `senses` (`id`, `entry_id`, `order_index`, `definition_ms`, `definition_en`) VALUES
  (20600, 20564, 1, 'kita; varian dialek bagi kiti (kata ganti nama diri pertama jamak inklusif). Lihat kiti.', 'we, us; dialectal variant of kiti (1st person plural inclusive pronoun). See kiti.'),
  (20601, 20565, 1, 'kita; varian dialek bagi kiti (kata ganti nama diri pertama jamak inklusif). Lihat kiti.', 'we, us; dialectal variant of kiti (1st person plural inclusive pronoun). See kiti.'),
  (20602, 20566, 1, 'supaya', '(so) that, in order to'),
  (20603, 20567, 1, 'kepada aku, pada aku, untuk aku; kata ganti nama diri pertama tunggal bentuk oblik / sendi (terbitan awalan sendi em- + aku, menandakan sasaran atau penerima).', 'to me, for me, at me (1st person singular oblique pronoun; derived from preposition em- + aku).'),
  (20604, 20568, 1, 'kepada kita, pada kita, untuk kita; kata ganti nama diri pertama jamak inklusif bentuk oblik / sendi (terbitan awalan sendi em- + kiti, merangkumi pendengar).', 'to us, for us (1st person plural inclusive oblique pronoun; derived from preposition em- + kiti).'),
  (20605, 20569, 1, 'kepada kami, pada kami, untuk kami; kata ganti nama diri pertama jamak eksklusif bentuk oblik / sendi (terbitan awalan sendi em- + kami, tidak merangkumi pendengar).', 'to us, for us (1st person plural exclusive oblique pronoun; derived from preposition em- + kami).'),
  (20606, 20570, 1, 'kepada kau, pada kamu, untukmu; kata ganti nama diri kedua tunggal bentuk oblik / sendi (terbitan awalan sendi em- + kau).', 'to you, for you (2nd person singular oblique pronoun; derived from preposition em- + kau).'),
  (20607, 20571, 1, 'kepada kalian, pada kamu semua; kata ganti nama diri kedua jamak bentuk oblik / sendi (terbitan awalan sendi em- + kaam).', 'to you all, for you all (2nd person plural oblique pronoun; derived from preposition em- + kaam).'),
  (20608, 20572, 1, 'kepada dia, pada dia, untuknya; kata ganti nama diri ketiga tunggal bentuk oblik / sendi (terbitan awalan sendi em- + io). Bentuk baku rasmi ialah mio (varian linguistik: miyo).', 'to him, to her, for him/her (3rd person singular oblique pronoun; derived from preposition em- + io). Standard form is mio.'),
  (20609, 20573, 1, 'kepada dia, pada dia; varian transkripsi linguistik bagi mio (kata ganti nama diri ketiga tunggal bentuk oblik). Bentuk baku rasmi ialah mio. Lihat mio.', 'to him/her; linguistic variant of standard mio (3rd person singular oblique pronoun). See mio.'),
  (20610, 20574, 1, 'kepada mereka, pada mereka, untuk mereka; kata ganti nama diri ketiga jamak bentuk oblik / sendi (terbitan awalan sendi em- + gai).', 'to them, for them (3rd person plural oblique pronoun; derived from preposition em- + gai).'),
  (20611, 20575, 1, 'kepada kalian, pada kamu semua; bentuk pendek atau varian percakapan bagi engkaam (kata ganti nama diri kedua jamak bentuk oblik). Lihat engkaam.', 'to you all; shortened conversational variant of engkaam (2nd person plural oblique pronoun). See engkaam.'),
  (20612, 20576, 1, 'itu; kata ganti nama tunjuk atau penentu bagi rujukan yang jauh dari penutur, dan penanda maklumat/definit dalam wacana', 'that; distal demonstrative pronoun and determiner (distal from speaker), also marks definiteness or previously introduced information in discourse'),
  (20613, 20577, 1, 'sana, itu nun di sana; kata ganti nama tunjuk atau penentu bagi rujukan yang jauh dari kedua-dua penutur dan pendengar tetapi masih kelihatan', 'that yonder; distal demonstrative pronoun and determiner (distal from both speaker and hearer, but visible)');

-- Table: examples (358 rows)
INSERT OR REPLACE INTO `examples` (`id`, `sense_id`, `sentence_bajau`, `highlight_word`, `sentence_ms`, `sentence_en`, `audio_url`) VALUES
  (3940, 18952, 'Ensan entelo emas akan pelua'' é pan ai lanyap.', 'akan', 'Walaupun telur emas yang hendak keluar, ia pun sudah lenyap.', 'Although a gold egg was about to come out, it was gone.', NULL),
  (3941, 18955, 'Kealapan jomo e no nikenang semomon.', 'alap', 'Kebaikan orang itu dikenang semua.', 'The goodness of that person is remembered by all.', NULL),
  (3942, 18955, 'Amzi pealap ruma''-ni boi temuan barat.', 'alap', 'Amzi membaiki rumahnya selepas dipukul ribut.', 'Amzi repaired his house after it was struck by the storm.', NULL),
  (3943, 18959, 'Amun kau pesuuk', 'amun', 'padi, apabila, bongkok', 'The rice plants, when ripened, they stoop over.', NULL),
  (3944, 18959, 'Kawa oyo tungan mapi daging sapi'' amun uun kawin.', 'amun', 'Kawah besar tempat memasak daging lembu jikalau ada perkahwinan.', 'A large cauldron is what (one) uses for cooking beef when there is a wedding.', NULL),
  (3945, 18960, 'Iyang peturi anak-ni diom bilik.', 'anak', 'Emak menidurkan anaknya di dalam bilik.', 'Mother put her child to sleep in the room.', NULL),
  (3946, 18960, 'Uwa mesti'' jo iyo mendo anak rojo e', 'anak', 'e         mara', 'e         mara', NULL),
  (3947, 18976, 'Baginou parai tu duo tumpuk.', 'bagi', 'Bahagikan padi ini kepada dua longgok.', 'Divide this rice into two heaps.', NULL),
  (3948, 18977, 'Tu no bagian dikau''.', 'bagian', 'Inilah bahagian kamu.', 'This is your share.', NULL),
  (3949, 18981, 'bangan bengen bongon', 'bangan', 'dan', 'X and company', NULL),
  (3950, 18985, 'Ngelaa'' jo poyo-no boi takad batu.', 'batu', 'Berdarahlah kakinya selepas terhantuk batu.', 'His foot bled after hitting a stone.', NULL),
  (3951, 19012, 'Me no gai betapukan diam', 'be-tapuk-an', 'di sana', 'Over there in the banana trees they are hiding.', NULL),
  (3952, 19017, 'Iyang meli parai ta'' kadai e.', 'beli', 'Emak membeli padi di kedai itu.', 'Mother bought rice at that shop.', NULL),
  (3953, 19017, 'Iyo mebeli diki''-ni sinsim amas.', 'beli', 'Dia membelikan adiknya sebentuk cincin emas.', 'He bought his younger sibling a gold ring.', NULL),
  (3954, 19023, 'Beta’ kami turi', 'beta', 'bekas', 'Mark fell on account of the coconut.', NULL),
  (3955, 19024, 'Bila ai bioso, teko no iyo lumaan dendangan-ni.', 'bila''', 'tidak, kaki', 'The leech could not stick to his leg.', NULL),
  (3956, 19026, 'Bila ai bioso, teko no iyo lumaan dendangan-ni.', 'bioso', 'tidak, kaki', 'The leech could not stick to his leg.', NULL),
  (3957, 19029, 'Lupus jo aku muat, bo''ku mooni', 'bo''', 'apabila', 'When morning came, the king brought (him) home.', NULL),
  (3958, 19029, '“… bo’ sanang atai', 'bo''', 'ada, jantung', 'I have heart trouble.', NULL),
  (3959, 19030, 'Boi jo gai mangan, turino gai.', 'boi', 'Selepas mereka makan, mereka pun tidur.', 'After they ate, they went to sleep.', NULL),
  (3960, 19030, 'Amzi nya'' boi mangan, ling-ni pedis betong-ni.', 'boi', 'Amzi tidak makan; katanya perutnya sakit.', 'Amzi did not eat; he said his stomach hurts.', NULL),
  (3962, 19039, 'Nginum kiti bu''e'' dingin tu.', 'bu''e''', 'Marilah kita minum air sejuk ini.', 'Let us drink this cold water.', NULL),
  (3963, 19039, 'Bése'' lumua'' lua'' moto-ni masa iyo nangis.', 'bu''e''', 'Air mata mengalir dari matanya semasa dia menangis.', 'Tears flowed from his eyes while he was crying.', NULL),
  (3964, 19039, 'Gai ningkoo'' ta'' sedi suang.', 'bu''e''', 'Mereka duduk di tepi sungai.', 'They sat at the riverbank.', NULL),
  (3965, 19039, 'Bu''e'' suang tu lumaan terus sampai ta'' laut.', 'bu''e''', 'Air sungai itu mengalir terus sampai ke laut.', 'The river water flows continuously into the sea.', NULL),
  (3966, 19040, 'Anak e ngenda'' bua'' kayu ta'' pitas.', 'bua''', 'Kanak-kanak itu melihat buah di atas pokok.', 'The child is looking at the fruit at the top of the tree.', NULL),
  (3967, 19046, 'Amzi boi muan buk e ta'' si Nisah.', 'buk', 'Amzi memberikan buku itu kepada Nisah.', 'Amzi gave the book to Nisah.', NULL),
  (3968, 19052, 'Bése'' lumua'' lua'' moto-ni masa iyo nangis.', 'bése''', 'Air mata mengalir dari matanya semasa dia menangis.', 'Tears flowed from his eyes while he was crying.', NULL),
  (3969, 19058, 'Jomo daras e jo engko e', 'daras', 'buka    tombol      telaga', 'buka    tombol      telaga', NULL),
  (3970, 19058, 'Jomo daras tilaw', 'daras', 'itu, ikan', 'Is that the fish you bought?', NULL),
  (3971, 19064, '…pelimpas lagi dela', 'dela', 'itu, oleh', 'At that time, by Allah', NULL),
  (3972, 19064, 'masang no dela', 'dela', 'di sana', 'He moved to Sayap.  He was also searched for there.', NULL),
  (3973, 19067, 'Dikau'' lagi binersi tungan langaw e ngentelo', 'di''', 'bersih, mana', 'Another (method) is to clean up places where flies lay eggs.', NULL),
  (3975, 19071, 'Tu no bagian dikau''.', 'dikau''', 'Inilah bahagian kamu.', 'This is your share.', NULL),
  (3976, 19085, 'Poon kayu e ebba'' masa angin benter.', 'ebba''', 'Pokok itu tumbang semasa angin kencang bertiup.', 'The tree toppled when the strong wind blew.', NULL),
  (3977, 19085, 'Boi Ai ebbaan Azizy poon saging e tapi boi ebba’', 'ebba''', 'rumah, masih', 'The house has (partially) burned [it is still standing].', NULL),
  (3978, 19086, 'Boi Ai ebbaan Azizy poon saging e tapi boi ebba’', 'ebba-an', 'rumah, masih', 'The house has (partially) burned [it is still standing].', NULL),
  (3979, 19088, 'Ellau tu panas tuu sampai karing tana''.', 'ellau', 'Hari ini sangat panas sehingga kering tanah.', 'Today is very hot until the earth is dried up.', NULL),
  (3980, 19092, 'Emma'' ko'' iyang no ninda'' ruma'' tu.', 'emma''', 'Ayah dan emaklah yang menjaga rumah ini.', 'Father and mother are the ones looking after this house.', NULL),
  (3984, 19102, 'jadi badu engko sebagai hadiah iyangku maku', 'engko''', 'ada, dari, panjang, itu', '... they used to have a saying from long ago that the tandasan cried.', NULL),
  (3985, 19102, 'Jomo daras e jo engko e', 'engko''', 'buka    tombol      telaga', 'buka    tombol      telaga', NULL),
  (3986, 19104, 'Ensan entelo emas akan pelua'' é pan ai lanyap.', 'ensan', 'Walaupun telur emas yang hendak keluar, ia pun sudah lenyap.', 'Although a gold egg was about to come out, it was gone.', NULL),
  (3988, 19107, 'Dikau'' lagi binersi tungan langaw e ngentelo', 'entelo', 'bersih, mana', 'Another (method) is to clean up places where flies lay eggs.', NULL),
  (3989, 19107, 'Ensan entelo emas akan', 'entelo', 'tidak, memberitahu', 'But the man knew even though they did not tell (him).', NULL),
  (3992, 19119, 'Itu no guuk', 'guuk', 'ini, itu', 'This is the knife that I bought at the weekly market.', NULL),
  (3993, 19123, 'Rupiah ingin mulé'' lingaw, tapi'' Mastura noo'' iyo ningkoo''.', 'ingin', 'duduk', 'Rupiah wanted to go home quickly, but Mastura made him sit down.', NULL),
  (3994, 19123, 'Iyo ingin supaya anakku', 'ingin', 'itu, anak, ambil', 'He wanted that my child would take care of the cows.', NULL),
  (3995, 19129, 'Itu no guuk', 'itu', 'ini, itu', 'This is the knife that I bought at the weekly market.', NULL),
  (3997, 19135, 'Emma'' ko'' iyang no ninda'' ruma'' tu.', 'iyang', 'Ayah dan emaklah yang menjaga rumah ini.', 'Father and mother are the ones looking after this house.', NULL),
  (4000, 19137, 'Kain tu binuat jadi badu ko'' tudung.', 'jadi', 'Kain ini dibuat menjadi baju dan tudung.', 'This cloth was made into a shirt and a headscarf.', NULL);
INSERT OR REPLACE INTO `examples` (`id`, `sense_id`, `sentence_bajau`, `highlight_word`, `sentence_ms`, `sentence_en`, `audio_url`) VALUES
  (4001, 19137, '… jadi iyo', 'jadi', 'pokok, boleh, jatuh, angin, keras', '… so it (the tree) can fall whenever the wind blows hard.', NULL),
  (4002, 19142, 'Boi jo gai mangan, turino gai.', 'jo', 'Selepas mereka makan, mereka pun tidur.', 'After they ate, they went to sleep.', NULL),
  (4003, 19142, 'Lupus jo aku muat, bo''-ku moo-ni', 'jo', 'apabila', 'When morning came, the king brought (him) home.', NULL),
  (4004, 19143, 'Patilauno kiti ta'' jomo e oron kampung tu.', 'jomo', 'Marilah kita bertanya kepada orang itu nama kampung ini.', 'Let us ask that person the name of this village.', NULL),
  (4005, 19143, 'Iyo no meketa jomo ta'' seberang suang.', 'jomo', 'Dialah yang menyeberangkan orang ke seberang sungai.', 'He was the one who crossed the people over to the other side of the river.', NULL),
  (4006, 19143, 'Kealapan jomo e no nikenang semomon.', 'jomo', 'Kebaikan orang itu dikenang oleh semua orang.', 'The goodness of that person is remembered by all.', NULL),
  (4007, 19143, 'Suang jomo teko diom majlis e.', 'jomo', 'Ramai orang datang ke majlis itu.', 'Many people arrived at the gathering.', NULL),
  (4008, 19143, 'Kampung tu iono pejomoon jomo lua'' darat.', 'jomo', 'Kampung ini ialah tempat persinggahan orang dari kawasan pedalaman.', 'This village is a meeting place for people from the inland.', NULL),
  (4009, 19146, 'Iyang meli parai ta'' kadai e.', 'kadai', 'Emak membeli padi di kedai itu.', 'Mother bought rice at that shop.', NULL),
  (4010, 19150, 'Boi jo gai mangan, turino gai.', 'kakan', 'Selepas mereka makan, mereka pun tidur.', 'After they ate, they went to sleep.', NULL),
  (4011, 19156, 'Amun kau pesuuk', 'kau''', 'padi, apabila, bongkok', 'The rice plants, when ripened, they stoop over.', NULL),
  (4012, 19156, 'Dikau'' lagi binersi tungan langaw e ngentelo', 'kau''', 'bersih, mana', 'Another (method) is to clean up places where flies lay eggs.', NULL),
  (4013, 19158, 'Anak e ngenda'' bua'' kayu ta'' pitas.', 'kayu', 'Kanak-kanak itu melihat buah di atas pokok.', 'The child is looking at the fruit at the top of the tree.', NULL),
  (4014, 19158, 'Poon kayu e ebba'' masa angin benter.', 'kayu', 'Pokok itu tumbang semasa angin kencang bertiup.', 'The tree toppled when the strong wind blew.', NULL),
  (4015, 19161, 'Dilaw Mark ketatakan', 'ketatakan', 'bekas, di sana', 'Yesterday Mark (unfortunately for him) dropped some money there in town.', NULL),
  (4016, 19163, 'Kealapan jomo e no nikenang semomon.', 'kealapan', 'Kebaikan orang itu dikenang oleh semua orang.', 'The goodness of that person is remembered by all.', NULL),
  (4017, 19189, 'Kerabau e pan pandai no betutur.', 'kerabau', 'Kerbau itu pandai bertutur.', 'The buffalo was able to speak.', NULL),
  (4018, 19189, 'Kerabau e mangan parai ta'' tana''.', 'kerabau', 'Kerbau itu makan padi di atas tanah.', 'The buffalo ate the unhusked rice on the ground.', NULL),
  (4019, 19194, 'Gai ngeta suang makai biduk diki''.', 'keta', 'Mereka menyeberang sungai menggunakan sampan kecil.', 'They crossed the river using a small boat.', NULL),
  (4020, 19194, 'Iyo no meketa jomo ta'' seberang suang.', 'keta', 'Dialah yang menyeberangkan orang ke seberang sungai.', 'He was the one who crossed the people over to the other side of the river.', NULL),
  (4021, 19204, 'Tekito le'' uwa'' e léko'' diom rumbau.', 'kito', 'Ternampak oleh anjing itu seekor ular di dalam semak.', 'The dog accidentally saw a snake in the bushes.', NULL),
  (4024, 19212, 'Uwa'' e nundug kucing sampai ta'' sedi poon kayu.', 'kucing', 'Anjing itu mengejar kucing sehingga ke tepi pokok.', 'The dog chased the cat to the side of the tree.', NULL),
  (4025, 19223, 'Lumua'' laa'' lua'' betis-nu.', 'laa''', 'Darah keluar dari kaki kamu.', 'Blood is coming out from your leg.', NULL),
  (4026, 19224, 'Iyo lumaan endiam taun sampai teko ta'' suang.', 'laan', 'Dia berjalan di dalam hutan sehingga tiba di sebatang sungai.', 'He walked through the forest until he reached a river.', NULL),
  (4027, 19224, 'Iyo lai ta'' dikau'' pulau.', 'laan', 'Dia melarikan diri ke sebuah pulau.', 'He fled to a certain island.', NULL),
  (4028, 19229, '…pelimpas lagi dela', 'lagi', 'itu, oleh', 'At that time, by Allah', NULL),
  (4029, 19229, 'Aku lagi langa man', 'lagi', 'semua', 'I am taller than all of you.', NULL),
  (4030, 19231, 'Iyo lai ta'' dikau'' pulau.', 'lai', 'Dia melarikan diri ke sebuah pulau.', 'He fled to a certain island.', NULL),
  (4031, 19234, 'Aku lagi langa man', 'langa', 'semua', 'I am taller than all of you.', NULL),
  (4034, 19253, 'Bo’ku likas ngogo siokoku', 'likas', 'rupiah wanted to return home quickly…', 'Rupiah wanted to return home quickly…', NULL),
  (4035, 19257, '…pelimpas lagi dela', 'limpas', 'itu, oleh', 'At that time, by Allah', NULL),
  (4039, 19272, 'Nya’ lagi iyo lumaan iyangni', 'lumaan', 'ibu, dengan, cincin', 'Before (her son) left, his mother sent (with him) a ring...', NULL),
  (4040, 19276, 'Lupus jo aku muat, bo''ku mooni', 'lupus', 'apabila', 'When morning came, the king brought (him) home.', NULL),
  (4041, 19278, 'Tekito le'' uwa'' e léko'' diom rumbau.', 'léko''', 'Ternampak oleh anjing itu seekor ular di dalam semak.', 'The dog accidentally saw a snake in the bushes.', NULL),
  (4042, 19281, 'Uwa'' e nundug kucing sampai ta'' sedi poon kayu.', 'makan', 'Anjing itu mengejar kucing sehingga ke tepi pokok.', 'The dog chased the cat to the side of the tree.', NULL),
  (4043, 19282, 'Dela pemalas e tekuri'' sampai tengellau.', 'malas', 'Lelaki pemalas itu tertidur sehingga tengah hari.', 'The lazy man overslept until noon.', NULL),
  (4044, 19285, 'Aku lagi langa man kam momon.', 'man', 'Aku lagi tinggi dari kamu semua.', 'I am taller than all of you.', NULL),
  (4045, 19287, 'Boi jo gai mangan, turino gai.', 'mangan', 'Selepas mereka makan, mereka pun tidur.', 'After they ate, they went to sleep.', NULL),
  (4046, 19287, 'Amzi nya'' boi mangan, ling-ni pedis betong-ni.', 'mangan', 'Amzi tidak makan; katanya perutnya sakit.', 'Amzi did not eat; he said his stomach hurts.', NULL),
  (4047, 19287, 'Boino ku mangan tadi.', 'mangan', 'Sudah saya makan tadi.', 'I already ate just now.', NULL),
  (4048, 19287, 'Kerabau e mangan parai ta'' tana''.', 'mangan', 'Kerbau itu makan padi di atas tanah.', 'The buffalo ate the unhusked rice on the ground.', NULL),
  (4049, 19287, 'Sedo'' e suang duri''-ni masa pinangan.', 'mangan', 'Ikan itu banyak tulangnya apabila dimakan.', 'The fish has many bones/thorns when eaten.', NULL),
  (4050, 19291, 'Pada masa e', 'masa', 'itu', 'Its texture is like that of sand, (it is) coarse.', NULL),
  (4051, 19300, 'Uwa mesti'' jo iyo mendo anak rojo e', 'mendo', 'e         mara', 'e         mara', NULL),
  (4052, 19305, 'Amun lumaan songom mesti’ makai suu'' enjaji soo nya'' tetindak.', 'mesti''', 'Kalau jalan (ketika waktu) malam, mesti memakai (lampu) suluh supaya tidak terpijak ular.', '‘If (you) travel at night, (you) should use a light so that (you) won’t accidentally step on a snake.', NULL),
  (4053, 19311, 'Iyo ai no mono’ jomo boi', 'mono''', 'siapa', 'He had now killed the men who had earlier killed his older brother.', NULL),
  (4054, 19317, 'Sinsim tu nianang le'' moto-ku ta'' lantai.', 'moto', 'Cincin ini dijumpai oleh saya di atas lantai.', 'This ring was found by my eyes on the floor.', NULL),
  (4055, 19318, 'Amzi boi muan buk e ta'' si Nisah.', 'muan', 'Amzi memberikan buku itu kepada Nisah.', 'Amzi gave the book to Nisah.', NULL),
  (4056, 19318, 'Amzi boi muan', 'muan', 'amzi gave the book to nisah', 'Amzi gave the book to Nisah.', NULL),
  (4057, 19320, 'Rupiah ingin mulé'' lingaw, tapi'' Mastura noo'' iyo ningkoo''.', 'mule''', 'duduk', 'Rupiah wanted to go home quickly, but Mastura made him sit down.', NULL);
INSERT OR REPLACE INTO `examples` (`id`, `sense_id`, `sentence_bajau`, `highlight_word`, `sentence_ms`, `sentence_en`, `audio_url`) VALUES
  (4058, 19328, 'Dikau'' lagi binersi tungan langaw e ngentelo', 'ngentelo', 'bersih, mana', 'Another (method) is to clean up places where flies lay eggs.', NULL),
  (4059, 19342, 'Anak e ngenda'' bua'' kayu ta'' pitas.', 'ngenda''', 'Kanak-kanak itu melihat buah di atas pokok.', 'The child is looking at the fruit at the top of the tree.', NULL),
  (4060, 19350, 'Nginum kiti bu''e'' dingin tu.', 'nginum', 'Marilah kita minum air sejuk ini.', 'Let us drink this cold water.', NULL),
  (4061, 19358, 'Ai akalan endo-nu aku, bara''-ni kau sakit.', 'ni', 'Isterimu telah membohongi aku, katanya kau sakit.', 'Your wife lied to me, she said you were sick.', NULL),
  (4064, 19368, 'Amzi nya'' boi mangan, ling-ni pedis betong-ni.', 'nya''', 'Amzi tidak makan; katanya perutnya sakit.', 'Amzi did not eat; he said his stomach hurts.', NULL),
  (4065, 19368, 'Tunganni nya sasaban e…', 'nya''', 'oleh', 'by; on account of', NULL),
  (4066, 19370, 'Ogo gai tabit ta’ kelinik kampung.', 'ogo', 'Mereka (pergi) melawat perawat di klinik kampung.', 'They went to a medical practitioner at the village clinic.', NULL),
  (4068, 19372, 'Boi opo'' Mali kayu é.', 'opo''', 'Mali sudah potong kayu itu.', 'Mali chopped the wood.', NULL),
  (4069, 19375, 'Kawa oyo tungan mapi daging sapi'' amun uun kawin.', 'oyo', 'Kawah besar tempat memasak daging lembu jikalau ada perkahwinan.', 'A large cauldron is what (one) uses for cooking beef when there is a wedding.', NULL),
  (4071, 19395, 'Pinda io pu’ ta’ Sayap. Pinemia pan io mé.', 'pan', 'Dia pindah pergi ke Sayap. Di sana pun dia dicari.', 'He moved to Sayap. He was also searched for there.', NULL),
  (4072, 19395, 'Mat Saleh mémang pan pinemia.', 'pan', 'Mat Saleh memang pun dicari.', 'Mat Salleh was definitely being hunted for.', NULL),
  (4073, 19396, 'Ellau tu panas tuu sampai karing tana''.', 'panas', 'Hari ini sangat panas sehingga kering tanah.', 'Today is very hot until the earth is dried up.', NULL),
  (4074, 19397, 'Kerabau e pan pandai no betutur.', 'pandai', 'Kerbau itupun pandailah bertutur.', 'The buffalo was able to speak.', NULL),
  (4075, 19406, 'Kerabau e mangan parai ta'' tana''.', 'parai', 'Kerbau itu makan padi di atas tanah.', 'The buffalo ate the unhusked rice on the ground.', NULL),
  (4076, 19406, 'Ta’ ongkob é penapukan parai.', 'parai', 'Di peti simpan itu (terletaknya) persorokan padi.', 'At/in the storage bin is the hiding place for paddy rice.', NULL),
  (4077, 19406, 'Iang meli parai ta'' kadai é.', 'parai', 'Emak membeli padi di kedai itu.', 'Mother buys rice at that shop.', NULL),
  (4078, 19406, 'Telu karung parai niboo lé'' gai engkadai.', 'parai', 'Tiga guni padi dibawa oleh mereka ke kedai.', 'Three sacks of rice were brought by them to the shop.', NULL),
  (4079, 19409, 'Ai jo gai lumaan, pelua'' no Deli lekat ta'' tungan-ni tapuk, bo''-ni pesikot ta'' dendo é.', 'pe', 'Lepas mereka pergi, keluarlah Deli dari tempat soroknya, kemudian mendekati wanita itu.', 'After they left, Deli came out from his hiding place and approached the woman.', NULL),
  (4081, 19416, 'Iyo no meketa jomo ta'' seberang suang.', 'peketa', 'Dialah yang menyeberangkan orang ke seberang sungai.', 'He was the one who crossed the people over to the other side of the river.', NULL),
  (4082, 19444, 'Iyang peturi anak-ni diom bilik.', 'peturi', 'Emak menidurkan anaknya di dalam bilik.', 'Mother put her child to sleep in the room.', NULL),
  (4083, 19446, 'Amzi pealap ruma''-ni boi temuan barat.', 'pealap', 'Amzi membaiki rumahnya selepas dipukul ribut.', 'Amzi repaired his house after it was struck by the storm.', NULL),
  (4084, 19487, 'Aku pesoyo ta’ Ramli', 'pesoyo', 'percaya, tidak', 'I believe Ramli, he is not prone to lying.', NULL),
  (4085, 19492, 'Petingkoo''no emma'' ta'' bangku kayu tu.', 'petingkoo''', 'Dudukkanlah ayah di bangku kayu ini.', 'Seat father on this wooden bench.', NULL),
  (4086, 19493, 'Jomo kampung ingin belajar pian lé'' noos amun ai kékét soo.', 'pian', 'Orang kampung ingin belajar bagaimana', 'The villagers wanted to know how to treat (someone) if a snake bites (him).', NULL),
  (4087, 19502, 'Boi Ai ebbaan Azizy poon saging e tapi boi ebba’', 'poon', 'rumah, masih', 'The house has (partially) burned [it is still standing].', NULL),
  (4088, 19504, 'Teingot-ku kisa sikot duo empu'' taun dau.', 'pu''', 'Aku teringatkan kisah dekat dua puluh tahun yang lalu.', 'I recalled a story from nearly twenty years ago.', NULL),
  (4089, 19519, 'Amzi pealap ruma''-ni boi temuan barat.', 'ruma''', 'Amzi membaiki rumahnya selepas dipukul ribut.', 'Amzi repaired his house after it was struck by the storm.', NULL),
  (4090, 19519, 'Emma'' ko'' iyang no ninda'' ruma'' tu.', 'ruma''', 'Ayah dan emaklah yang menjaga rumah ini.', 'Father and mother are the ones looking after this house.', NULL),
  (4091, 19520, 'Sapi''-ni ai rungai diom taun.', 'rungai', 'Lembunya telah hilang di dalam hutan.', 'His cow is missing in the forest.', NULL),
  (4092, 19525, 'A. Saging e', 'saging', 'ikan, sungai', 'I cleaned the fish at the river.', NULL),
  (4093, 19525, 'Boi Ai ebbaan Azizy poon saging e tapi boi ebba’', 'saging', 'rumah, masih', 'The house has (partially) burned [it is still standing].', NULL),
  (4094, 19528, 'Sambil dela e nembali', 'sambil', 'dekat, tengok, pokok, semasa, dengan, orang ramai', 'I drew near to look at the tree while conversing with people.', NULL),
  (4095, 19530, 'Tapi’ ensan pian pan malé’ tereso, atai-ku sukup sanang.', 'sanang', 'Tapi walau macam manapun penat terasa, hatiku cukup senang.', 'But however tired (I) felt, I was very happy.', NULL),
  (4096, 19531, 'Sapi''-ni ai rungai diom taun.', 'sapi''', 'Lembunya telah hilang di dalam hutan.', 'His cow is missing in the forest.', NULL),
  (4097, 19531, 'Kawa oyo tungan mapi daging sapi'' amun uun kawin.', 'sapi''', 'Kawah besar tempat memasak daging lembu jikalau ada perkahwinan.', 'A large cauldron is what (one) uses for cooking beef when there is a wedding.', NULL),
  (4098, 19537, 'Gai ningkoo'' ta'' sedi suang.', 'sedi', 'Mereka duduk di tepi sungai.', 'They sat at the riverbank.', NULL),
  (4100, 19540, 'Aku selalu nguse’ nguse-an', 'selalu', 'basuh', 'I always wash (my) hands before eating.', NULL),
  (4103, 19562, 'Sikot no ellaw, uun', 'sikot', 'apabila, dekat, siapa', 'When it was near daylight, those who had gone out now arrived.', NULL),
  (4104, 19566, 'Iyo mebeli diki''-ni sinsim amas.', 'sinsim', 'Dia membelikan adiknya sebentuk cincin emas.', 'He bought his younger sibling a gold ring.', NULL),
  (4105, 19566, 'Sinsim tu nianang le'' moto-ku ta'' lantai.', 'sinsim', 'Cincin ini dijumpai oleh saya di atas lantai.', 'This ring was found by my eyes on the floor.', NULL),
  (4106, 19576, 'Bésé'' lumua'' lua'' moto-ni masa io nangis.', 'suang', 'Air mata mengalir dari matanya semasa dia menangis.', 'Tears flowed from his eyes while he was crying.', NULL),
  (4107, 19576, 'Gai ngeta suang makai biduk diki''.', 'suang', 'Mereka menyeberang sungai menggunakan sampan kecil.', 'They crossed the river using a small boat.', NULL),
  (4108, 19576, 'Suang jomo teko diom majlis é.', 'suang', 'Ramai orang datang ke majlis itu.', 'Many people arrived at the gathering.', NULL),
  (4109, 19576, 'Io lumaan endiam taun sampai teko ta'' suang.', 'suang', 'Dia berjalan di dalam hutan sehingga tiba di sebatang sungai.', 'He walked through the forest until he reached a river.', NULL),
  (4110, 19576, 'Bué'' suang tu lumaan terus sampai ta'' laut.', 'suang', 'Air sungai itu mengalir terus sampai ke laut.', 'The river water flows continuously into the sea.', NULL),
  (4111, 19579, 'suk + R', 'suk', 'buat, ramai', 'to make (many) thin', NULL),
  (4112, 19582, 'Iyo ingin supaya anakku', 'supaya', 'itu, anak, ambil', 'He wanted that my child would take care of the cows.', NULL),
  (4113, 19586, 'Amun kau pesuuk', 'suuk', 'padi, apabila, bongkok', 'The rice plants, when ripened, they stoop over.', NULL),
  (4114, 19587, 'Ogo gai tabit ta’ kelinik kampung', 'tabit', 'jika, rumah, orang ramai', 'If the kitchens were below (the house), she took people', NULL),
  (4117, 19595, 'Ai jo gai lumaan, pelua tunganni tapuk', 'tapuk', 'dari, letak, dan', 'After they left, Deli came out from his hiding place and approached the woman.', NULL);
INSERT OR REPLACE INTO `examples` (`id`, `sense_id`, `sentence_bajau`, `highlight_word`, `sentence_ms`, `sentence_en`, `audio_url`) VALUES
  (4118, 19595, 'Me no gai betapukan diam', 'tapuk', 'di sana', 'Over there in the banana trees they are hiding.', NULL),
  (4119, 19597, 'Dilaw Mark ketatakan', 'tatak', 'bekas, di sana', 'Yesterday Mark (unfortunately for him) dropped some money there in town.', NULL),
  (4120, 19601, 'Io lumaan endiam taun sampai teko ta'' suang.', 'taun', 'Dia berjalan di dalam hutan sehingga tiba di sebatang sungai.', 'He walked through the forest until he reached a river.', NULL),
  (4121, 19601, 'Sapi''-ni ai rungai diom taun.', 'taun', 'Lembunya telah hilang dalam hutan.', 'His cow is missing in the forest.', NULL),
  (4122, 19602, 'Jadi pelua’no té''  bué''-ni.', 'té''', 'Jadi keluarlah airnya.', 'Its water then gushes out.', NULL),
  (4123, 19602, 'Iyang-nu té'' aku tu!', 'té''', 'Ibumu adalah aku!', 'I am your mother!', NULL),
  (4124, 19614, 'Io lai endiam taun sampay teko ta'' dembua'' suang.', 'teko', 'Dia lari ke dalam hutan sehingga tiba di sebuah sungai.', 'He fled into the forest until (he) arrived at a certain river.', NULL),
  (4125, 19614, 'Aku tu bau teko pitu eng Kuta’ Belud.', 'teko', 'Aku ni baru tiba sini di Kota Belud.', 'I have just arrived here in Kota Belud.', NULL),
  (4126, 19616, 'Telu karung parai niboo le'' gai ta'' kadai.', 'telu', 'Tiga guni padi dibawa oleh mereka ke kedai.', 'Three sacks of rice were brought by them to the shop.', NULL),
  (4127, 19631, 'Tilauno mio pasal hal e.', 'tilau', 'Tanyalah kepada dia tentang perkara itu.', 'Ask him/her about that matter.', NULL),
  (4128, 19631, 'Patilauno kiti ta'' jomo e oron kampung tu.', 'tilau', 'Marilah kita bertanya kepada orang itu nama kampung ini.', 'Let us ask that person the name of this village.', NULL),
  (4129, 19642, 'Petingkoo''no emma'' ta'' bangku kayu tu.', 'tingkoo''', 'Dudukkanlah ayah di bangku kayu ini.', 'Seat father on this wooden bench.', NULL),
  (4130, 19642, 'Gai ningkoo'' ta'' sedi suang.', 'tingkoo''', 'Mereka duduk di tepi sungai.', 'They sat at the riverbank.', NULL),
  (4131, 19653, 'Itu no guuk penebong-nu boo’ é.', 'tu', 'Inilah pisau penebangmu (untuk) buluh itu.', 'This is the knife you should use for chopping the bamboo.', NULL),
  (4132, 19657, 'Kawa oyo tungan mapi daging sapi'' amun uun kawin.', 'tungan', 'Kawah besar tempat memasak daging lembu jikalau ada perkahwinan.', 'A large cauldron is what (one) uses for cooking beef when there is a wedding.', NULL),
  (4133, 19657, 'Dikau'' lagi binersi tungan langaw e ngentelo.', 'tungan', 'Satu (cara) lagi membersihkan tempat lalat bertelur.', 'Another (method) is to clean up places where flies lay eggs.', NULL),
  (4134, 19658, 'Boi jo gai mangan, turino gai.', 'turi', 'Selepas mereka makan, mereka pun tidur.', 'After they ate, they went to sleep.', NULL),
  (4135, 19658, 'Iyang peturi anak-ni diom bilik.', 'turi', 'Emak menidurkan anaknya di dalam bilik.', 'Mother put her child to sleep in the room.', NULL),
  (4136, 19658, 'Dela pemalas e tekuri'' sampai tengellau.', 'turi', 'Lelaki pemalas itu tertidur sehingga tengah hari.', 'The lazy man overslept until noon.', NULL),
  (4137, 19660, 'Kerabau é pan pandai no betutur.', 'tutur', 'Kerbau itupun pandai bertutur.', 'The buffalo was able to speak.', NULL),
  (4138, 19664, 'Tuyungan-ni boé'' tebu é pé diam kawa.', 'tuyung', 'air', 'She added sugar cane water into the cauldron.', NULL),
  (4139, 19675, 'Uun iyang-nu mé?', 'uun', 'Ada ibumu situ?', 'Is your mother there?', NULL),
  (4140, 19675, 'Sikot no ellau, uun no gai teko boi lumaan é.', 'uun', '(Bila hari) hampir siang, adalah mereka tiba setelah berjalan.', 'When it was near daylight, those who had gone out now arrived.', NULL),
  (4141, 19676, 'Tekito le'' uwa'' e léko'' diom rumbau.', 'uwa''', 'Ternampak oleh anjing itu seekor ular di dalam semak.', 'The dog accidentally saw a snake in the bushes.', NULL),
  (4142, 19676, 'Uwa'' e nundug kucing sampai ta'' sedi poon kayu.', 'uwa''', 'Anjing itu mengejar kucing sehingga ke tepi pokok.', 'The dog chased the cat to the side of the tree.', NULL),
  (4348, 20414, 'Tungan kubu British é ngam bana engko’ susa bana sinerang olé’ askar Gipun.', 'Gipun', 'Tempat berkubu British itu sesuai sekali dan susah sangat (untuk) diserang oleh askar Jepun', 'The location of the British fort was strategic and very difficult to be attacked by the Japanese army.', NULL),
  (4349, 19371, 'Dela pisok é tinandukan no olé'' gai laan ngogo entelaga.', 'olé''', 'Lelaki buta itu ditunjukkan jalan oleh mereka yang menuju ke telaga.', 'The blind man was shown by them the path that went to the well.', NULL),
  (4350, 19371, 'Jomo too é mara’ kampung é pinirenta ole’ jomo daras…', 'olé''', 'Orang tua itu memberitahu (bahawa) kampung itu diperintah oleh orang yang kuat…', 'The old man said that the village was governed by a powerful man…', NULL),
  (4351, 20415, 'Ian boi opo'' Nisah?', 'opo''', 'Apa yang dipecahkan Nisah?', 'What did Nisah break?', NULL),
  (4352, 20416, 'Lapas é io pinelua'', tapi'' nidokop pan  balik.', 'pinelua''', 'Lepas itu dia dibebaskan, tetapi ditangkap semula.', 'After that he was released, but was caught again.', NULL),
  (4353, 19380, 'Sini’ sinsaung aku posok  meruma’, tekito-ku iang-ku ngerait badu Mali é.', 'posok', 'Pagi ini aku masuk ke rumah, aku terlihat ibuku menjahit baju Mali itu.', 'This morning when I entered the house, I saw that my mother was sewing Mali’s shirt.', NULL),
  (4354, 19388, 'Abis mangan bongon pakir pan bepulé’ no.', 'pakir', '(Setelah) habis makan, golongan agamawan pun baliklah.', 'After eating, the men with religious knowledge went home.', NULL),
  (4355, 19389, 'Paksa’-ni aku posok diam keréta’.', 'paksa', 'Dia paksa aku masuk dalam kereta.', 'He forced me to enter the car.', NULL),
  (4356, 19390, 'Rupo-rupo-ni, kakal pala teingot-ni.', 'pala', 'Rupa-rupanya, kekal pula teringatnya.', 'Apparently, she still kept being remembered of it.', NULL),
  (4357, 19522, 'Bila pelua'' sab anak-ni pitu'' kau''.', 'sab', 'Bila keluar juga anaknya tujuh orang.', 'When the baby came out—there were seven.', NULL),
  (4358, 19522, 'Bila teko ka''-ni pé,  "Ai koyo no sab kam tu, minggo kam ngendo''?"', 'sab', 'Bila tiba kakaknya ke sana, (dia berkata): "Sudah kaya juga kamu ni, dari mana kamu dapat (kekayaan itu)?"', '‘When her older sister arrived there, (she said):  “You have become rich. Where did you get (your wealth)?', NULL),
  (4359, 20419, 'Kerabau tu binuat ulun jo té’, sinoo’ narik-narik pengila tandasan é.', 'tandasan', 'Kerbau ini dijadikan hamba saja, disuruh menarik-narik abah-abah kilang tebu itu.', 'The water buffalo was made into a slave, it was forced to pull the harness for the sugarcane mill.', NULL),
  (4360, 19602, 'Amun nya'' buat-ku sab, bo'' aduin no té’ aku!', 'té’', 'Kalau aku tidak buat juga (apa yang aku janjikan), maka adukanlah aku!', 'If I don’t do (what I promised), then go ahead and report me!', NULL),
  (4361, 19606, 'Tapi'' bila sikot ellau, io ai teturi sampai telak.', 'teturi', 'Tapi bila hampir siang, dia telah tertidur sampai terang (di luar)', 'But when it was nearly day, he fell asleep (and did not awake) until it was bright (outside).', NULL),
  (4364, 19610, 'Minggo boi tedakan-nu diing é?', 'tedakan', 'Di mana kau siangkan ikan tu?', 'Where did you clean the fish?', NULL),
  (4365, 19610, 'Ensuang diing é boi tedakan-ku.', 'tedakan', 'Aku sudah siangkan ikan tu di sungai.', 'I cleaned the fish at the river.', NULL),
  (4366, 19630, 'Dong kayu keros tigad-nu engko’ guuk é.', 'tigad', 'Jangan kau potong kayu keras dengan pisau itu.', 'Don’t chop hardwood with that knife.', NULL),
  (4367, 19647, 'Togor bana tiang pagar é.', 'togor', 'Tegak benar tiang pagar itu.', 'That fence post stands very straight.', NULL),
  (4368, 19442, 'Boi petogor Mali tiang pagar é.', 'petogor', 'Mali telah menegakkan tiang pagar itu.', 'Mali erected the fence post', NULL),
  (4369, 19660, 'Ai jo jomo too é abis betutur io pan pungkau.', 'tutur', 'Selesai saja orang tua itu abis bertutur, dia (Hussin) pun bangun.', 'After the old man had finished speaking, he (Hussin) woke up.', NULL),
  (4371, 20427, 'Ai peketa kuda’ pe dembila’ suang.', 'peketa', 'Kuda (itu) telah menyeberang ke sebelah sungai.', 'The horse crossed to the other side of the river.', NULL),
  (4372, 20429, 'Dau-da kono'' uun jomo tu temban ta'' dikau'' kampung.', 'kampung', 'Dulu-dulu konon ada orang ni (yang) tinggal di sebuah kampung.', 'Long ago, it is said, there was a man who lived in a certain village.', NULL),
  (4374, 19542, 'Azizy boi sémbét-ku engko'' surat é.', 'sémbét', 'Aku kejar Azizy dengan surat tu.', 'I chased Azizy with the letter.', NULL),
  (4375, 20434, 'Ta''  dia'' poon suka''.', 'ta''', 'Di bawah pokok kelapa.', '(At) below the coconut tree.', NULL),
  (4376, 20436, 'tekito-ni jo uwa'' e lulai sorop meniik, terus iyo memia te'' tungan-ni tapuk.', 'terus', 'Apabila dilihatnya anjing itu berlari mendaki, dia terus mencari tempat bersembunyi.', 'When he saw the dog running toward him, he immediately searched for a place to hide.', NULL);
INSERT OR REPLACE INTO `examples` (`id`, `sense_id`, `sentence_bajau`, `highlight_word`, `sentence_ms`, `sentence_en`, `audio_url`) VALUES
  (4377, 20437, 'Rupiah peloot diam sumpat, semono-mono ngeraa iyo.', 'semono-mono', 'Rupiah menyeluk ke dalam semak, tiba-tiba dia berteriak.', 'Rupiah reached into the underbrush, and suddenly he screamed.', NULL),
  (4378, 20438, 'Uun entedo Hassan pu'' ta'' laat dembua'' nuut bono''.', 'entedo', 'Ada suatu ketika Hassan pergi ke negeri lain menyertai pertempuran.', 'One time Hassan went yonder to another country to fight.', NULL),
  (4380, 20440, 'Jarang bana no pan muat gula'' tebu tu betiru.', 'betiru', 'Sangat jarang orang membuat gula tebu pada masa sekarang.', 'Very rarely do people make cane sugar nowadays.', NULL),
  (4381, 20441, 'Minggo kam boi turi debui''?', 'debui''', 'Di manakah kamu tidur malam tadi?', 'Where did you sleep last night?', NULL),
  (4382, 20442, 'Sinsaung awal lagi iyang-ni ngogo ruma'' rojo.', 'sinsaung', 'Awal pagi lagi ibunya pergi menziarahi istana raja.', 'When it was still early in the morning, his mother went to the palace.', NULL),
  (4383, 20443, 'Rupo-rupo-ni, kakal pala teingot-ni.', 'rupo-rupo-ni', 'Rupa-rupanya, masih pula dia teringat.', 'Apparently, she still remembered the matter.', NULL),
  (4384, 20444, 'tekito-ku ruun dekiit jo jamban mitu.', 'mitu', 'Saya lihat hanya ada sedikit tandas di sini.', 'I see that there are few toilets here.', NULL),
  (4385, 20445, 'Aku ningkoo''-ningkoo'' jo mé meluar.', 'mé', 'Saya duduk-duduk sahaja sana di luar.', 'I just kept sitting there outside.', NULL),
  (4386, 20446, 'Bo''-ku likas ngogo sioko-ku dela é mu'' dembila'' ruma''.', 'mu''', 'Lalu aku lekas pergi kepada abang sulungku di sana di rumah seberang.', 'Then I quickly went to my oldest brother over yonder in the house across.', NULL),
  (4387, 20447, 'Aku tu bau teko pitu engKuta'' Belud.', 'pitu', 'Saya ini baru sahaja sampai ke sini di Kota Belud.', 'I have just arrived here in Kota Belud.', NULL),
  (4388, 20448, 'Somo-somo gai sinoo'' moo endo pé ta'' ruma'' emma''-ni.', 'pe', 'Bersama-sama mereka disuruh membawa isteri pergi ke situ ke rumah bapa mereka.', 'Together they were ordered to bring their wives there to their father''s house.', NULL),
  (4389, 20449, 'Andang no tabiat-ni bege sejak dau lagi.', 'andang', 'Sememangnya sudah menjadi tabiatnya begitu sejak dahulu lagi.', 'It has certainly been his nature like that since long ago.', NULL),
  (4390, 20450, 'Patut no iyo nya'' teko, ruun kerjo-ni.', 'patut', 'Patutlah dia tidak datang, ada kerjanya.', 'No wonder he did not come, he had work to do.', NULL),
  (4391, 20451, 'Kadang-kadang iyo teko pitu ngenda'' kami.', 'kadang-kadang', 'Kadang-kadang dia datang ke sini melihat kami.', 'Sometimes he comes here to visit us.', NULL),
  (4392, 20452, 'Mendangaino kau boi ngenda'' wayang é?', 'mendangaino', 'Berapa kalikah kamu sudah menonton wayang itu?', 'How many times have you watched that movie?', NULL),
  (4393, 20453, 'Bangi dilau io boi mulé'' pitu.', 'bangi', 'Kelmarin dulu dia sudah pulang ke sini.', 'He returned here the day before yesterday.', NULL),
  (4394, 20454, 'Suang dikau'' no kiti ketemu balik ta'' Kuta'' Belud.', 'suang dikau''', 'Lusa barulah kita berjumpa lagi di Kota Belud.', 'The day after tomorrow we will meet again in Kota Belud.', NULL),
  (4395, 20455, 'Panas bana langa ellaw tu.', 'langa ellaw', 'Sangat panas waktu tengah hari ini.', 'It is very hot this midday.', NULL),
  (4396, 20456, 'Mungkin Tuhan ingin mekitoon kekuasaan-ni.', 'mungkin', 'Mungkin Tuhan hendak memperlihatkan kekuasaan-Nya.', 'Perhaps God wanted to show His power.', NULL),
  (4398, 19208, '"Pemia-ti koso, dong kau susa atai," ling-ni.', 'koso', '"Kita akan mencari (dia), jangan kamu susah hati," katanya.', '“We will look for (him), don''t you worry,” he said.', NULL),
  (4399, 19260, 'Rupiah ingin mulé'' lingau, tapi'' Mastura noo'' io ningkoo''.', 'lingau', 'Rupiah ingin pulang secepat mungkin, tetapi Masturi membawa dia (untuk) duduk.', 'Rupiah wants to go back home quickly, but Mastura brings her to sit.', NULL),
  (4400, 20457, 'Uun entedo Hassan pu'' ta'' laat dembua'' nuut bono''.', 'pu''', 'Ada suatu ketika Hassan pergi ke sana nun ke negeri lain menyertai pertempuran.', 'One time Hassan went yonder to another country to fight.', NULL),
  (4401, 19559, 'Sian oron-nu?', 'Sian', 'Siapakah nama kamu?', 'What is your name? (lit. Who is your name?)', NULL),
  (4402, 19559, 'Ta'' sian kau boi turi debui''?', 'sian', 'Di (rumah) siapakah kamu tidur malam tadi?', 'At whose place did you sleep last night?', NULL),
  (4403, 19309, 'Minggo tungan mandi mitu?', 'Minggo', 'Di manakah tempat mandi di sini?', 'Where is a place to bathe here?', NULL),
  (4404, 19309, 'Minggo kam boi turi debui''?', 'Minggo', 'Di manakah kamu tidur malam tadi?', 'Where did you sleep last night?', NULL),
  (4405, 19101, 'Badu enggo boi pené''-nu?', 'enggo', 'Baju manakah yang telah kamu pilih?', 'Which shirt did you choose?', NULL),
  (4407, 19493, 'Pian le''-ku nya'' sugul bana, teingot-ku hal é.', 'Pian', 'Bagaimanakah caranya aku tidak sangat bersedih, teringat aku akan hal itu.', 'How could I not be very upset, remembering that matter.', NULL),
  (4408, 19055, 'Kiniro jo dangai orang boi pinanggil é si''.', 'dangay', 'Dikira saja berapa orang yang telah dipanggil tadi.', 'Let it be counted how many people were invited.', NULL),
  (4409, 20458, 'Pak pan tilau, "ian boo-nu é, Kin?"', 'Iyan', 'Katak pun bertanya, "apakah yang kamu bawa itu, Kin?"', 'The frog asked, "what are you to bring, Kin?"', NULL),
  (4410, 20459, 'Embérén kau mulé'' pitu balik?', 'embérén', 'Bilakah kamu akan pulang ke sini semula?', 'When will you return here again?', NULL),
  (4411, 20460, 'Ngini kau nya'' maku kebanaran maku?', 'Ngini', 'Mengapa kamu tidak meminta kebenaran dengan aku?', 'Why did you not ask permission of me?', NULL),
  (4412, 20461, '"Bulika kiti besoro ta'' makama?" ling rojo.', 'ka', '"Bolehkah kita bertengkar tentang hal ini di mahkamah?" kata raja.', '"Can we dispute this in court?" said the king.', NULL),
  (4413, 20462, 'Moo kau ano é pitu, timba é.', 'ano', 'Bawalah apa namanya itu ke sini, baldi itu.', 'Bring that what''s-it-called here, the bucket.', NULL),
  (4416, 20467, '"Enggo di''-ku Amat?" ling Inang.', 'enggo', '"Manakah adikku Amat?" kata Inang.', '"Where is my younger brother Amat?" said Inang.', NULL),
  (4417, 20468, 'Dong kau susa atai, ling-ni.', 'Dong', 'Jangan kamu berasa susah hati, katanya.', 'Don''t you worry, he said.', NULL),
  (4418, 20468, 'Dong no kam tinau, kiti ruun pengawal mitu.', 'Dong', 'Jangan kamu semua berasa takut, kita ada pengawal di sini.', 'Don''t you all be afraid, we have guards here.', NULL),
  (4419, 20469, 'Daa no kiti nipu, daa no kiti muat keraatan.', 'Daa', 'Janganlah kita menipu, janganlah kita membuat kejahatan.', 'Let us not cheat, let us not do bad things.', NULL),
  (4420, 20469, 'Daa kau manas e, aku kekuri jo.', 'Daa', 'Janganlah engkau marah, aku hanya bergurau sahaja.', 'Don''t be angry! I was just playing around.', NULL),
  (4421, 20470, 'Baa''no kiti mulé'' pitu balik sebelum petang.', 'Baa''', 'Marilah kita pulang ke sini semula sebelum waktu petang.', 'Come on, let us return here before evening.', NULL),
  (4422, 20471, 'Pasi kam ningkoo'' mitu diam ruma''.', 'Pasi', 'Silalah kamu semua duduk di sini di dalam rumah.', 'Please sit here inside the house.', NULL),
  (4423, 20472, 'Mulé'' jo no kam, baya''-ni no aku temban mitu.', 'baya''-ni', 'Pulang sajalah kamu semua, biarkan aku tinggal di sini.', 'You all go home, just let me stay here.', NULL),
  (4424, 20472, 'Aa... baya''-ni! Kakan-ku jo iyan uun.', 'baya''-ni', 'Ahh... biarkanlah! Aku makan sahaja apa yang ada.', 'Ahh, let it be! I will eat whatever is available.', NULL),
  (4425, 20473, 'Temban no using e en-diata'' jing ruma''.', 'diata''', 'Kucing itu berada di atas bumbung zink rumah.', 'The cat stayed on top of the zinc roof of the house.', NULL),
  (4426, 19140, 'Temban no using e en-jata'' jing...', 'jata''', 'Kucing itu berada di atas bumbung zink...', 'The cat stayed on top of the zinc (roof)...', NULL),
  (4427, 20474, 'Sangsuriang pan lumaan no engko'' Situmang en-diom taun.', 'diom', 'Sangsuriang berjalan bersama Situmang ke dalam hutan.', 'Sangsuriang traveled with Situmang into the forest.', NULL),
  (4428, 19069, 'Sangsuriang pan lumaan no engko'' Situmang en-diam taun.', 'diam', 'Sangsuriang berjalan bersama Situmang ke dalam hutan.', 'Sangsuriang traveled with Situmang into the forest.', NULL),
  (4429, 19069, 'lua'' en-diam lubang langkaw', 'diam', 'dari dalam lubang atau terowong yang panjang', 'from within the long tunnel', NULL),
  (4430, 19269, 'Masa gai kepo lua'' ta'' kayangan...', 'lua''', 'Pada masa mereka melompat turun dari kayangan...', 'At the time they jumped down from the heavens...', NULL),
  (4431, 19269, '...iyo ngagad-ngagad lua'' kemuap lagi...', 'lua''', '...dia terus menunggu sejak waktu petang lagi...', '...she continued to wait since the afternoon...', NULL);
INSERT OR REPLACE INTO `examples` (`id`, `sense_id`, `sentence_bajau`, `highlight_word`, `sentence_ms`, `sentence_en`, `audio_url`) VALUES
  (4432, 20476, 'Daa temban ta'' lua'' bilik amun uran.', 'lua''', 'Jangan berada di luar bilik jika hujan.', 'Don''t stay outside the room when it rains.', NULL),
  (4433, 19068, 'Beranti iyo ta'' dia'' poon kayu.', 'dia''', 'Dia berhenti di bawah pokok.', 'He stopped beneath a tree.', NULL),
  (4434, 19068, 'ta'' dia'' poon suka''', 'dia''', 'di bawah pohon kelapa', 'beneath the coconut tree', NULL),
  (4435, 19049, 'Io nanduk-nanduk poon saging embunda'' beluang gua é.', 'embunda''', 'Ia menanduk-nanduk pohon pisang di hadapan pintu gua itu.', 'She would butt her horns against the banana tree in front of the door to the cave.', NULL),
  (4436, 19679, 'Dendo embuli'' bana ngentan ta'' torong puyut.', 'embuli''', 'Wanita yang di paling belakang memegang hujung sapu tangan.', 'The woman in the very back holds the end of the handkerchief.', NULL),
  (4437, 19679, 'Embuli'' ruma'' é.', 'embuli''', 'Di belakang rumah itu.', 'Behind the house.', NULL),
  (4438, 19537, 'ta'' sedi selang', 'sedi', 'di tepi laut / pesisir pantai', 'beside the sea', NULL),
  (4439, 19065, 'Gai temban ta'' dembila'' suang.', 'dembila''', 'Mereka tinggal di seberang sungai.', 'They live on the other side of the river.', NULL),
  (4440, 20477, 'Dau-dau tu kono'' iko bana kerabaw tenga'' padang.', 'tenga''', 'Dahulu kala dikatakan sangat banyak kerbau di tengah padang.', 'A long time ago it is said that there were many buffalo in the middle of the field.', NULL),
  (4441, 20477, 'en-tenga''=ni', 'tenga''', 'di bahagian tengahnya', 'in the middle of it', NULL),
  (4442, 20478, 'Dendo embuli'' bana ngentan ta'' torong puyut.', 'torong', 'Wanita yang di paling belakang memegang hujung sapu tangan.', 'The woman in the very back holds the end of the handkerchief.', NULL),
  (4443, 20479, 'Iyo lumaan ta'' sedi kuanan.', 'kuanan', 'Dia berjalan di sebelah kanan.', 'He walked on the right side.', NULL),
  (4444, 20480, 'Pasi ilik ta'' sedi gibang dau.', 'gibang', 'Sila tengok ke sebelah kiri dahulu.', 'Please look to the left side first.', NULL),
  (4445, 20540, 'Pitu'' urang dendo mangan sesama ta'' dapor.', NULL, 'Tujuh orang perempuan makan bersama di dapur.', 'Seven women ate together in the kitchen.', NULL),
  (4446, 20541, 'Iko urang teko meli paray ta'' pasar.', NULL, 'Banyak orang datang membeli padi di pasar.', 'Many people came to buy paddy at the market.', NULL),
  (4447, 20542, 'Empat orang dendo laan ngeririk.', NULL, 'Empat orang perempuan pergi menebas rumput.', 'Four women went clearing the brush.', NULL),
  (4448, 20543, 'Teko iyo ta'' dembua'' suang langkaw.', NULL, 'Sampailah dia di sebuah sungai yang luas.', 'He arrived at a certain large river.', NULL),
  (4449, 20543, 'Boi mendok dembua'' ruma'' ta'' tana'' e.', NULL, 'Telah didirikan sebuah rumah di tanah itu.', 'A house was built on that land.', NULL),
  (4450, 20544, 'Ngenda'' dikau'' ungut paray boi pinene''.', NULL, 'Mengambil seungut beras yang telah dipilih.', 'Taking one coconut-shell measure of chosen rice.', NULL),
  (4451, 20545, 'Tambai dikau'' pejut sira'' ta'' guwayan e.', NULL, 'Tambah secubit garam ke dalam masakan itu.', 'Add a pinch of salt to that dish.', NULL),
  (4452, 20546, 'Meli telu supak paray ta'' tamu Kota Belud.', NULL, 'Membeli tiga cupak beras di tamu Kota Belud.', 'Bought three supak of rice at the Kota Belud tamu.', NULL),
  (4453, 20547, 'Duo gantang beras tinu'' ta'' timbukan paray.', NULL, 'Dua gantang beras disimpan di dalam tempat simpan beras.', 'Two gantangs of rice were stored in the rice container.', NULL),
  (4454, 20548, 'Duru'' paray e teko telu bandu taun tu.', NULL, 'Hasil tuaian padi itu mencecah tiga bandu tahun ini.', 'The rice harvest yield reached three bandu this year.', NULL),
  (4455, 20549, 'Telu karung paray boi nina'' ta'' pantaran.', NULL, 'Tiga guni padi telah dijemur di pelantar.', 'Three sacks of paddy were dried on the platform.', NULL),
  (4456, 20550, 'Isi'' paray e ta'' diom karung.', NULL, 'Isikan padi itu ke dalam guni.', 'Fill the rice paddy into the sack.', NULL),
  (4457, 20551, 'Empat sibur paray tinanom ling jomo kampung.', NULL, 'Empat petak sawah padi ditanam oleh orang kampung.', 'Four paddy plots were planted by the villagers.', NULL),
  (4458, 20552, 'Duo koo kelangkayan papan tu.', NULL, 'Dua jengkal lebar papan ini.', 'Two finger-spans is the width of this plank.', NULL),
  (4459, 20553, 'Deransang langkay tali tu.', NULL, 'Sejengkal panjang tali ini.', 'This rope is one finger-span long.', NULL),
  (4460, 20554, 'Ukur ransang tangan nu ta'' meja.', NULL, 'Ukur jengkal tangan kamu pada meja.', 'Measure your hand span on the table.', NULL),
  (4461, 20555, 'Telor kayu e telu seta'' ketebol ni.', NULL, 'Batang kayu itu berketebalan tiga hasta.', 'That wood trunk is three cubits thick.', NULL),
  (4462, 20556, 'Duang depo kelalomon suang e.', NULL, 'Dua depa kedalaman sungai itu.', 'The river''s depth is two fathoms.', NULL),
  (4463, 20557, 'Kerot buluk e duo unga'' panjang ni.', NULL, 'Kerat buluh itu panjangnya dua ruas.', 'Cut that bamboo to the length of two internodes.', NULL),
  (4464, 20558, 'Iko bangso lauk ta'' diom laut.', NULL, 'Banyak jenis ikan di dalam laut.', 'There are many kinds of fish in the sea.', NULL),
  (4465, 20559, 'Kita jomo bangso Sama.', NULL, 'Kita orang berbangsa Sama.', 'We are people of the Sama nation.', NULL),
  (4466, 20560, 'Duo tumpuk tana'' binuan ta'' binaian.', NULL, 'Dua longgok tanah dibuang di halaman.', 'Two heaps of soil were deposited in the compound.', NULL),
  (4467, 20561, 'Bagi aku dikau'' kerot kayu api tu.', NULL, 'Beri saya sekerat kayu api ini.', 'Give me one piece of this firewood.', NULL),
  (4468, 20562, 'Dikau'' petak buas teko ta'' mata.', NULL, 'Setitis air mata menitis di mata.', 'A drop of tear welled up in the eye.', NULL),
  (4469, 20563, 'Beli dikau'' limping sigup ta'' kaday.', NULL, 'Beli selempeng tembakau di kedai.', 'Buy one bundle of tobacco at the shop.', NULL),
  (4470, 20564, 'Duo sekat saging masak boi bineli ta'' tamu.', NULL, 'Dua sikat pisang masak telah dibeli di tamu.', 'Two hands of ripe bananas were bought at the market.', NULL),
  (4471, 20565, 'Dikau'' tundun saging nabak ta'' tana''.', NULL, 'Setandan pisang jatuh ke tanah.', 'A bunch of bananas fell to the ground.', NULL),
  (4472, 20566, 'Duo ingkot sayur bineli ling iyaku.', NULL, 'Dua ikat sayur dibeli oleh saya.', 'Two bundles of vegetables were bought by me.', NULL),
  (4473, 20567, 'Dikau'' banan sapi laan mangan ta'' padang.', NULL, 'Sekawan lembu sedang makan rumput di padang.', 'A herd of cows was grazing in the pasture.', NULL),
  (4474, 20568, 'Simpan lauk e ta'' diom mangkuk.', NULL, 'Simpan lauk itu di dalam mangkuk.', 'Keep the dish in a bowl.', NULL),
  (4475, 20569, 'Mangan iyo duo mangkuk sup lauk.', NULL, 'Dia makan dua mangkuk sup ikan.', 'He ate two bowls of fish soup.', NULL),
  (4476, 19056, 'Dangan dendo teko ta'' ruma''.', NULL, 'Seorang perempuan datang ke rumah.', 'One woman arrived at the house.', NULL),
  (4477, 19080, 'Duangan anak e ngentan bua''.', NULL, 'Dua orang kanak-kanak itu memegang buah.', 'Two children are holding fruits.', NULL),
  (4478, 19617, 'Telungan dendo lai pule''.', NULL, 'Tiga orang perempuan lari pulang.', 'Three women ran home.', NULL),
  (4479, 20570, 'Telu em-bua'' entelo bineli ta'' tamu.', NULL, 'Tiga biji telur dibeli di pasar tamu.', 'Three eggs were bought at the market.', NULL),
  (4480, 20570, 'Empat em-bua'' ruma'' runtuh tinabak ribut.', NULL, 'Empat buah rumah runtuh dilanda ribut.', 'Four houses collapsed due to the storm.', NULL),
  (4481, 20571, 'Bagi aku telu sarat duren tu.', NULL, 'Beri saya tiga ulas durian ini.', 'Give me three segments of this durian.', NULL);
INSERT OR REPLACE INTO `examples` (`id`, `sense_id`, `sentence_bajau`, `highlight_word`, `sentence_ms`, `sentence_en`, `audio_url`) VALUES
  (4482, 20572, 'Tambai de-n-sudu'' gula ta'' kupi nu.', NULL, 'Tambah sesudu gula ke dalam kopi kamu.', 'Add one spoonful of sugar to your coffee.', NULL),
  (4483, 20573, 'Kiniket lindo''-ni lé'' namuk.', 'lé''', 'Dahinya digigit oleh nyamuk.', 'His forehead was bitten by a mosquito.', NULL),
  (4484, 20574, 'Ngeletup tangan-ku lé'' guuk é.', 'lé''', 'Tanganku melepuh kerana parang itu.', 'My hand blistered on account of that machete.', NULL),
  (4485, 20575, 'Tabit é sanang atai lé'' Mastura boi noos Rupiah.', 'lé''', 'Penyembuh itu gembira dengan cara Mastura mengubati Rupiah.', 'The healer was pleased with how Mastura medicated Rupiah.', NULL),
  (4486, 20576, 'Lumaan iyo ko'' see''ni.', NULL, 'Dia berjalan dengan kawannya.', 'He traveled with his friend.', NULL),
  (4487, 20577, 'Baginda Ali nya''no teko pelua'' lua'' mé sampaino betiru.', 'sampai', 'Baginda Ali tidak dapat keluar dari dahulu sampailah sekarang.', 'Baginda Ali could not get out from then until now.', NULL),
  (4488, 20578, 'Io teturi sampai telak.', 'sampai', 'Dia tertidur sehingga (hari) terang.', 'He fell asleep until it was bright outside.', NULL),
  (4489, 20579, 'Saging e boi tinobang ling dela e.', NULL, 'Pokok pisang itu telah ditebang oleh lelaki itu.', 'The banana tree was cut down by the man.', NULL),
  (4490, 19098, 'Sangsuriang mule'' me-ruma''.', NULL, 'Sangsuriang pulang ke rumah.', 'Sangsuriang went home.', NULL),
  (4491, 19098, 'Temban using e en-jata'' jing.', NULL, 'Kucing itu berada di atas bumbung zink.', 'The cat was on top of the zinc roof.', NULL),
  (4492, 19241, 'Iyo lai lekat ta'' kampungni.', NULL, 'Dia melarikan diri dari kampungnya.', 'He fled from his village.', NULL),
  (4493, 19241, 'Kulintangan bana binuat lekat ta'' tembaga''.', NULL, 'Kulintangan tulen dibuat daripada tembaga.', 'Genuine kulintangan were made from brass metal.', NULL),
  (4494, 20580, 'Aii''! Langkau bana bua'' kayu tu.', NULL, 'Wah! Besar sungguh buah pokok itu.', 'Wow! The fruit of this tree is really huge.', NULL),
  (4495, 20581, 'Adaka! Nya'' tekito ling-ku io teko muli''.', 'adaka', 'Masakan! Tidak kusangka dia sudah pulang.', 'Really?! I had no idea he had come home.', NULL),
  (4496, 20582, 'Oi''! Pakau kau maku.', NULL, 'Hoi! Kamu mengejutkan saya.', 'Hey! You startled me.', NULL),
  (4497, 20583, 'Si''! Pelaan man parai é!', 'si''', 'Suh! Pergi dari padi itu!', 'Shoo! Get away from that rice paddy!', NULL),
  (4498, 20584, 'Sé''! Palai uwa'' tu!', NULL, 'Hus! Halau anjing ini!', 'Shoo! Drive this dog away!', NULL),
  (4499, 20585, 'Adui! Pedi'' bana betong-ku tu.', 'adui', 'Aduh! Sakit betul perut saya ini.', 'Ouch! This stomach of mine really hurts.', NULL),
  (4500, 20586, 'Adoi! Nabak aku ta'' jambatan.', NULL, 'Adoi! Saya terjatuh di jambatan.', 'Ouch! I fell on the bridge.', NULL),
  (4501, 20587, 'Ba, laanno kiti betiru.', 'ba', 'Baiklah, mari kita bertolak sekarang.', 'Alright, let''s leave now.', NULL),
  (4502, 20588, 'Si''! Pelaan man parai é!', 'man', 'Suh! Pergi dari padi itu!', 'Shoo! Get away from that rice paddy!', NULL),
  (4503, 19365, 'Bangunno kau, ellau ai langa.', 'no', 'Bangunlah kamu, hari sudah tinggi.', 'Wake up, the day is already late.', NULL),
  (4504, 19365, 'Lumaanno kiti betiru.', 'no', 'Berjalanlah kita sekarang.', 'Let''s get going now.', NULL),
  (4505, 19076, 'Buanin-bi do'' bué'' susu tu!', 'do''', 'Berikanlah kalian air susu itu!', 'Give that milk!', NULL),
  (4506, 19076, 'Bau do'' io teko.', 'do''', 'Baru sahaja tadi dia tiba.', 'He arrived just now.', NULL),
  (4507, 19205, 'Namuk kono'' oyo bana masa é.', 'kono''', 'Nyamuk kononnya sangat besar pada masa itu.', 'Mosquitoes were said to be very large at that time.', NULL),
  (4508, 19209, 'Te-kito=ku ruun dekiit jo buas ta'' diam baa e.', NULL, 'Tampak olehku ada sedikit sahaja beras di dalam pasu itu.', 'I saw there was only a little rice inside the jar.', NULL),
  (4509, 19209, 'Ruma''-ku ta'' sedi suang.', NULL, 'Rumah saya di tepi sungai.', 'My house is beside the river.', NULL),
  (4510, 19136, 'Pinda io pu’ ta’ Sayap. Pinemia pan iyo mé.', NULL, 'Dia pindah pergi ke Sayap. Di sana pun dia dicari.', 'He moved to Sayap. Even there he was searched for.', NULL),
  (4511, 19136, 'Amzi nya’ boi mangan, io pedis betong.', NULL, 'Amzi tidak makan, dia sakit perut.', 'Amzi did not eat, he has a stomach ache.', NULL),
  (4512, 19111, 'Boi jo gai mangan, turino gai.', NULL, 'Selepas mereka makan, mereka pun tidur.', 'After they ate, they went to sleep.', NULL),
  (4513, 19111, 'Bila pelua'' sab anak-ni pitu'' kau'', ngoyak no gai.', NULL, 'Bila keluar juga anaknya tujuh orang, mereka pun berteriak.', 'When her seven children also came out, they shouted.', NULL),
  (4514, 20589, 'Aku boi meli buas ta'' tamu.', NULL, 'Saya telah membeli beras di tamu.', 'I bought rice at the market.', NULL),
  (4515, 20589, 'Ngini kau mau aku?', NULL, 'Mengapakah kamu memanggil saya?', 'Why did you summon me?', NULL),
  (4516, 20590, 'Lumaan no kiti betiru.', NULL, 'Berjalanlah kita sekarang.', 'Let us go now.', NULL),
  (4517, 20592, 'Kami muat kerijo tu lekat sinsubuh.', NULL, 'Kami membuat kerja itu sejak pagi lagi.', 'We have been doing this work since early morning.', NULL),
  (4518, 20593, 'Bangun no kau, ellaw ai langa.', NULL, 'Bangunlah kamu, hari sudah tinggi.', 'Wake up, the day is already late.', NULL),
  (4519, 20593, 'Ngini kau mau aku?', NULL, 'Mengapa kamu memanggil saya?', 'Why did you call me?', NULL),
  (4520, 20594, 'Kaam no pio dulu.', NULL, 'Kalianlah pergi ke sana dahulu.', 'You all go there first.', NULL),
  (4521, 20595, 'Minggo kam boi turi debui’?', NULL, 'Di mana kalian tidur semalam?', 'Where did you all sleep last night?', NULL),
  (4522, 20596, 'Pinemia pan iyo mé.', NULL, 'Di sana pun dia dicari.', 'Even there he was searched for.', NULL),
  (4523, 20597, '"Pemia-ti koso, dong kau susa atai," ling-ni.', '-ti', '"Kita akan mencarinya, janganlah kamu susah hati," katanya.', '"We will search for it, don''t worry," he said.', NULL),
  (4524, 20597, 'Inan no tempat-ti peliukan diri.', '-ti', 'Inilah tempat kita melarikan diri.', 'This is our place to escape.', NULL),
  (4525, 20598, 'Iyang-nu té'' aku tu!', NULL, 'Ibumu adalah aku!', 'I am your mother!', NULL),
  (4526, 20598, 'Ai akalan endo-nu aku.', NULL, 'Isterimu telah memperdayakan aku.', 'Your wife deceived me.', NULL),
  (4527, 20599, 'Buan-in bi do'' bue'' susu tu!', NULL, 'Berikanlah kalian air susu itu!', 'Give that milk!', NULL),
  (4528, 20599, 'Ruma''-bi minggo tungan-ni?', NULL, 'Di manakah letaknya rumah kalian?', 'Where is your house located?', NULL),
  (4529, 20602, 'Amun lumaan songom mesti’ makai suu'' enjaji soo nya'' tetindak.', 'enjaji', 'Kalau jalan (ketika waktu) malam, mesti memakai (lampu) suluh supaya tidak terpijak ular.', 'If (you) travel at night, (you) should use a light so that (you) won’t accidentally step on a snake.', NULL),
  (4530, 20603, 'Oi''! Pakau kau maku.', NULL, 'Hoi! Kamu mengejutkan saya.', 'Hey! You startled me.', NULL),
  (4531, 20603, 'Buan-nu maku buas e.', NULL, 'Berikanlah kepada saya beras itu.', 'Give that rice to me.', NULL);
INSERT OR REPLACE INTO `examples` (`id`, `sense_id`, `sentence_bajau`, `highlight_word`, `sentence_ms`, `sentence_en`, `audio_url`) VALUES
  (4532, 20604, 'Buan-in bi engkiti peluang tu.', NULL, 'Berikanlah kepada kita peluang ini.', 'Give this opportunity to us.', NULL),
  (4533, 20605, 'Bara''-nu engkami amun tekito-nu iyo.', NULL, 'Beritahulah kepada kami jika kamu ternampak dia.', 'Tell us if you see him.', NULL),
  (4534, 20606, 'Aku moli engkau kuih tu.', NULL, 'Saya membeli untukmu kuih ini.', 'I bought this cake for you.', NULL),
  (4535, 20607, 'Boi biniata-ku engkaam semomon duit e.', NULL, 'Sudah saya bayarkan kepada kalian semua wang itu.', 'I have paid the money to all of you.', NULL),
  (4536, 20608, 'Buan-ku mio bua'' kayu e.', NULL, 'Saya berikan kepadanya buah pokok itu.', 'I gave him the fruit.', NULL),
  (4537, 20610, 'Kinetoan enggai no pasal hal tu.', NULL, 'Diketahui oleh mereka / disampaikan kepada mereka tentang hal itu.', 'It was made known to them regarding this matter.', NULL),
  (4538, 20612, 'Buas é boi beli-ni ensemio sini''.', 'é', 'Beras itu telah dibelinya di pekan tadi.', 'He bought that rice at the market earlier.', NULL),
  (4540, 20613, 'Buas u'' boi beli-ni ensemio sini''.', 'u''', 'Beras nun di sana itu telah dibelinya di pekan tadi.', 'He bought that rice over there at the market earlier.', NULL);

